def transform(grid):
    if not grid or not grid[0]:
        return grid

    H, W = len(grid), len(grid[0])
    bg = grid[0][0]

    # Find single-cell components (markers)
    markers = {}  # position -> color
    visited = set()

    for r in range(H):
        for c in range(W):
            if (r, c) not in visited:
                cells = []
                color = grid[r][c]
                stack = [(r, c)]
                visited.add((r, c))
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            stack.append((nr, nc))

                if len(cells) == 1:
                    markers[(r, c)] = color
                elif len(cells) > 1:
                    cells.sort()
                    mid = cells[len(cells)//2][0]
                    markers[(r, c)] = (cells, mid)

    # Sort by row position, left to right
    marker_positions = sorted((r, c) for (r, c) in markers)

    # Sort blocks by top-left position  
    block_components = []
    for (r, c), data in markers.items():
        if isinstance(data, tuple) and len(data[0]) > 1:
            cells, mrow = data
            cells.sort()
            block_components.append({
                'color': data[0][0],
                'cells': cells,
                'median_r': mrow,
                'area': len(cells)
            })

    block_components.sort(key=lambda x: (x['median_r'], x[1]))

    marker_values = [markers[(r, c)] for (r, c) in marker_positions if isinstance(markers[(r, c)), int]]

    # Map blocks to marker values by position matching
    for i, block in enumerate(block_components):
        if i < len(marker_values):
            mv = marker_values[i]
            for r, c in block['cells']:
                grid[r][c] = mv

    return grid
